/****************************************************************************
 * apps/packages/demos/contest2026_388_velaink/stroke.h
 *
 * 墨灵 VelaInk — 笔迹数据结构与插值
 * 大赛：2026 首届 openvela AI 硬件开发者大赛 · 388 队
 *
 * Licensed under the Apache License, Version 2.0 (the "License");
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VELAINK_STROKE_H
#define __VELAINK_STROKE_H

#include <stdint.h>

/* 单个笔画（一次落笔到抬笔之间的连续轨迹） */
struct velaink_stroke
{
  float *pts;        /* [x0,y0, x1,y1, ...] 归一化坐标 0.0~1.0 */
  int    npts;       /* 点的个数 */
  int    cap;        /* 已分配容量（点数） */
};

/* 一幅作品 = 若干笔画 */
struct velaink_drawing
{
  struct velaink_stroke *strokes;
  int                    nstrokes;
  int                    cap;
};

/* ---------- 生命周期 ---------- */

int  velaink_stroke_init(struct velaink_stroke *s, int cap);
void velaink_stroke_free(struct velaink_stroke *s);
int  velaink_stroke_push(struct velaink_stroke *s, float x, float y);

int  velaink_drawing_init(struct velaink_drawing *d, int cap);
void velaink_drawing_free(struct velaink_drawing *d);
int  velaink_drawing_add(struct velaink_drawing *d, float x, float y);
/* 结束当前笔画（抬笔），开始下一笔 */
int  velaink_drawing_pen_up(struct velaink_drawing *d);

/* ---------- 平滑 ---------- */

/* Catmull-Rom 样条插值：把稀疏控制点变成平滑笔迹
 * samples: 每两个控制点之间插入的采样数（越大越平滑，点也越多）
 * 返回 0 成功；失败返回负值
 */
int velaink_stroke_smooth(const struct velaink_stroke *in,
                          struct velaink_stroke *out, int samples);

/* 按弧长重采样，保证相邻点间距均匀（避免进给速度抖动） */
int velaink_stroke_resample(const struct velaink_stroke *in,
                            struct velaink_stroke *out, float step_mm,
                            float width_mm, float height_mm);

/* ---------- 内置示例 ---------- */

/* 生成一个示例作品（一颗心），用于自检与演示 */
int velaink_demo_heart(struct velaink_drawing *d);

#endif /* __VELAINK_STROKE_H */

/****************************************************************************
 * apps/packages/demos/contest2026_388_velaink/gcode.h
 *
 * 墨灵 VelaInk — G-code 生成（面向 GRBL 1.1f / CoreXY 写字机）
 *
 * 设计要点：
 *  - 只输出笛卡尔坐标，CoreXY 运动学转换交给 GRBL 控制板（"大脑+小脑"架构）
 *  - 归一化坐标按工作区等比缩放并居中，天然适配不同幅面
 *  - 抬笔/落笔用 Z 轴（舵机抬笔结构），带 plungy 进给与延时
 *  - 所有数值参与限位保护，越界即报错，绝不把机器送出轨
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef __VELAINK_GCODE_H
#define __VELAINK_GCODE_H

#include <stdio.h>
#include "stroke.h"

/* 机器参数：大鱼 DayuWriter V2.21 Pro（200 x 196 mm 有效工作区） */
struct velaink_machine
{
  float width_mm;      /* X 行程 */
  float height_mm;     /* Y 行程 */
  float margin_mm;     /* 四周留白 */
  float pen_up_mm;     /* 抬笔高度（Z） */
  float pen_down_mm;   /* 落笔高度（Z） */
  float feed_mm_min;   /* 绘制进给速度 */
  float plunge_mm_min; /* Z 轴进给速度 */
  float safe_z_mm;     /* 快速移动时的安全高度 */
};

void velaink_machine_default(struct velaink_machine *m);

/* 归一化坐标 -> 机器坐标（等比缩放 + 居中），结果写入 *mx/*my */
void velaink_map_point(const struct velaink_machine *m,
                       float nx, float ny, float *mx, float *my);

/* 生成完整 G-code 到 fp
 * 返回生成的行数，出错返回负值
 */
int velaink_gcode_emit(FILE *fp, const struct velaink_drawing *d,
                       const struct velaink_machine *m);

/* 生成 G-code 到文件路径（便于在板子上落盘 .nc 文件） */
int velaink_gcode_to_file(const char *path, const struct velaink_drawing *d,
                          const struct velaink_machine *m);

#endif /* __VELAINK_GCODE_H */

/****************************************************************************
 * apps/packages/demos/contest2026_388_velaink/stroke.c
 *
 * 墨灵 VelaInk — 笔迹插值与示例生成
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdlib.h>
#include <math.h>
#include "stroke.h"

#define VELAINK_PI 3.14159265358979323846f

int velaink_stroke_init(struct velaink_stroke *s, int cap)
{
  if (cap < 2)
    {
      cap = 2;
    }

  s->pts = (float *)calloc((size_t)cap * 2, sizeof(float));
  if (!s->pts)
    {
      s->npts = 0;
      s->cap  = 0;
      return -1;
    }

  s->npts = 0;
  s->cap  = cap;
  return 0;
}

void velaink_stroke_free(struct velaink_stroke *s)
{
  if (s->pts)
    {
      free(s->pts);
    }

  s->pts  = NULL;
  s->npts = 0;
  s->cap  = 0;
}

static int stroke_grow(struct velaink_stroke *s)
{
  int    ncap = s->cap ? s->cap * 2 : 16;
  float *np   = (float *)realloc(s->pts, (size_t)ncap * 2 * sizeof(float));

  if (!np)
    {
      return -1;
    }

  s->pts = np;
  s->cap = ncap;
  return 0;
}

int velaink_stroke_push(struct velaink_stroke *s, float x, float y)
{
  if (s->npts >= s->cap && stroke_grow(s) < 0)
    {
      return -1;
    }

  s->pts[s->npts * 2]     = x;
  s->pts[s->npts * 2 + 1] = y;
  s->npts++;
  return 0;
}

int velaink_drawing_init(struct velaink_drawing *d, int cap)
{
  if (cap < 1)
    {
      cap = 1;
    }

  d->strokes = (struct velaink_stroke *)calloc((size_t)cap,
                                               sizeof(struct velaink_stroke));
  if (!d->strokes)
    {
      d->nstrokes = 0;
      d->cap      = 0;
      return -1;
    }

  d->nstrokes = 0;
  d->cap      = cap;
  return 0;
}

void velaink_drawing_free(struct velaink_drawing *d)
{
  int i;

  if (!d->strokes)
    {
      return;
    }

  for (i = 0; i < d->nstrokes; i++)
    {
      velaink_stroke_free(&d->strokes[i]);
    }

  free(d->strokes);
  d->strokes  = NULL;
  d->nstrokes = 0;
  d->cap      = 0;
}

/* 追加一个点。d->nstrokes == 0 时自动开一笔 */
int velaink_drawing_add(struct velaink_drawing *d, float x, float y)
{
  struct velaink_stroke *cur;

  if (d->nstrokes == 0)
    {
      if (d->nstrokes >= d->cap)
        {
          return -1; /* 容量由 init 决定，示例场景足够 */
        }

      if (velaink_stroke_init(&d->strokes[d->nstrokes], 64) < 0)
        {
          return -1;
        }

      d->nstrokes++;
    }

  cur = &d->strokes[d->nstrokes - 1];
  return velaink_stroke_push(cur, x, y);
}

int velaink_drawing_pen_up(struct velaink_drawing *d)
{
  if (d->nstrokes == 0 || d->nstrokes >= d->cap)
    {
      return -1;
    }

  if (d->strokes[d->nstrokes - 1].npts == 0)
    {
      return 0; /* 空笔画，不新增 */
    }

  if (velaink_stroke_init(&d->strokes[d->nstrokes], 64) < 0)
    {
      return -1;
    }

  d->nstrokes++;
  return 0;
}

/****************************************************************************
 * Catmull-Rom 插值
 ****************************************************************************/

static void catmull_rom(float p0[2], float p1[2], float p2[2], float p3[2],
                        float t, float out[2])
{
  float t2 = t * t;
  float t3 = t2 * t;
  int   k;

  for (k = 0; k < 2; k++)
    {
      out[k] = 0.5f * ((2.0f * p1[k]) +
                       (-p0[k] + p2[k]) * t +
                       (2.0f * p0[k] - 5.0f * p1[k] + 4.0f * p2[k] -
                        p3[k]) * t2 +
                       (-p0[k] + 3.0f * p1[k] - 3.0f * p2[k] + p3[k]) * t3);
    }
}

int velaink_stroke_smooth(const struct velaink_stroke *in,
                          struct velaink_stroke *out, int samples)
{
  int i;
  int j;

  if (!in || !out || in->npts < 2 || samples < 1)
    {
      return -1;
    }

  if (velaink_stroke_init(out, (in->npts - 1) * samples + 1) < 0)
    {
      return -1;
    }

  for (i = 0; i < in->npts - 1; i++)
    {
      float p0[2];
      float p1[2];
      float p2[2];
      float p3[2];
      int   i0 = (i > 0) ? (i - 1) : 0;
      int   i2 = (i + 1 < in->npts) ? (i + 1) : (in->npts - 1);
      int   i3 = (i + 2 < in->npts) ? (i + 2) : (in->npts - 1);

      p1[0] = in->pts[i * 2];
      p1[1] = in->pts[i * 2 + 1];
      p2[0] = in->pts[i2 * 2];
      p2[1] = in->pts[i2 * 2 + 1];
      p0[0] = in->pts[i0 * 2];
      p0[1] = in->pts[i0 * 2 + 1];
      p3[0] = in->pts[i3 * 2];
      p3[1] = in->pts[i3 * 2 + 1];

      for (j = 0; j < samples; j++)
        {
          float o[2];

          catmull_rom(p0, p1, p2, p3, (float)j / (float)samples, o);
          if (velaink_stroke_push(out, o[0], o[1]) < 0)
            {
              return -1;
            }
        }
    }

  /* 收尾点 */

  velaink_stroke_push(out, in->pts[(in->npts - 1) * 2],
                      in->pts[(in->npts - 1) * 2 + 1]);
  return 0;
}

/****************************************************************************
 * 等弧长重采样
 ****************************************************************************/

int velaink_stroke_resample(const struct velaink_stroke *in,
                            struct velaink_stroke *out, float step_mm,
                            float width_mm, float height_mm)
{
  float acc = 0.0f;
  float px;
  float py;
  int   i;

  if (!in || !out || in->npts < 2 || step_mm <= 0.0f)
    {
      return -1;
    }

  if (velaink_stroke_init(out, in->npts * 4 + 16) < 0)
    {
      return -1;
    }

  px = in->pts[0];
  py = in->pts[1];
  velaink_stroke_push(out, px, py);

  for (i = 1; i < in->npts; i++)
    {
      float cx = in->pts[i * 2];
      float cy = in->pts[i * 2 + 1];
      float dx = (cx - px) * width_mm;
      float dy = (cy - py) * height_mm;
      float seg = sqrtf(dx * dx + dy * dy);

      if (seg < 1e-6f)
        {
          continue;
        }

      acc += seg;
      if (acc >= step_mm)
        {
          velaink_stroke_push(out, cx, cy);
          acc = 0.0f;
        }

      px = cx;
      py = cy;
    }

  /* 保证末点完整 */

  if (out->npts > 0)
    {
      float lx = in->pts[(in->npts - 1) * 2];
      float ly = in->pts[(in->npts - 1) * 2 + 1];

      if (out->pts[(out->npts - 1) * 2] != lx ||
          out->pts[(out->npts - 1) * 2 + 1] != ly)
        {
          velaink_stroke_push(out, lx, ly);
        }
    }

  return 0;
}

/****************************************************************************
 * 内置示例：一颗心（参数方程）
 *   x = 16 sin^3 t
 *   y = 13 cos t - 5 cos 2t - 2 cos 3t - cos 4t
 ****************************************************************************/

int velaink_demo_heart(struct velaink_drawing *d)
{
  const int   n = 96;
  int         i;
  float       minx = 1e9f;
  float       maxx = -1e9f;
  float       miny = 1e9f;
  float       maxy = -1e9f;
  static float raw[96 * 2];

  for (i = 0; i < n; i++)
    {
      float t = 2.0f * VELAINK_PI * (float)i / (float)n;
      float st = sinf(t);
      float x  = 16.0f * st * st * st;
      float y  = 13.0f * cosf(t) - 5.0f * cosf(2.0f * t) -
                 2.0f * cosf(3.0f * t) - cosf(4.0f * t);

      raw[i * 2]     = x;
      raw[i * 2 + 1] = y;

      if (x < minx) minx = x;
      if (x > maxx) maxx = x;
      if (y < miny) miny = y;
      if (y > maxy) maxy = y;
    }

  /* Y 轴翻转（屏幕坐标向下为 +Y，机器坐标向上为 +Y）并归一化到 0..1 */

  for (i = 0; i < n; i++)
    {
      float nx = (raw[i * 2] - minx) / (maxx - minx);
      float ny = (maxy - raw[i * 2 + 1]) / (maxy - miny);

      if (velaink_drawing_add(d, nx, ny) < 0)
        {
          return -1;
        }
    }

  /* 闭合 */

  velaink_drawing_add(d, (raw[0] - minx) / (maxx - minx),
                      (maxy - raw[1]) / (maxy - miny));
  return 0;
}

/****************************************************************************
 * apps/packages/demos/contest2026_388_velaink/gcode.c
 *
 * 墨灵 VelaInk — G-code 生成
 *
 * 输出面向 GRBL 1.1f：G21/G90/G94，Z 轴抬落笔，笛卡尔坐标。
 * CoreXY 的运动学解算由下位控制板完成，本模块只负责"画什么"。
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <math.h>
#include "gcode.h"

void velaink_machine_default(struct velaink_machine *m)
{
  m->width_mm      = 200.0f;  /* 大鱼 DayuWriter V2.21 Pro */
  m->height_mm     = 196.0f;
  m->margin_mm     = 10.0f;
  m->pen_up_mm     = 5.0f;
  m->pen_down_mm   = 0.0f;
  m->feed_mm_min   = 3000.0f;
  m->plunge_mm_min = 500.0f;
  m->safe_z_mm     = 5.0f;
}

void velaink_map_point(const struct velaink_machine *m,
                       float nx, float ny, float *mx, float *my)
{
  float usable_w = m->width_mm - 2.0f * m->margin_mm;
  float usable_h = m->height_mm - 2.0f * m->margin_mm;

  *mx = m->margin_mm + nx * usable_w;
  *my = m->margin_mm + ny * usable_h;
}

static int in_bounds(const struct velaink_machine *m, float x, float y)
{
  return (x >= -0.001f) && (x <= m->width_mm + 0.001f) &&
         (y >= -0.001f) && (y <= m->height_mm + 0.001f);
}

int velaink_gcode_emit(FILE *fp, const struct velaink_drawing *d,
                       const struct velaink_machine *m)
{
  int lines = 0;
  int s;

  if (!fp || !d || !m)
    {
      return -1;
    }

  /* ---- 文件头 ---- */

  fprintf(fp, "; VelaInk - AI creative writing robot\n");
  fprintf(fp, "; generated by openvela (contest2026_388_ajiejie)\n");
  fprintf(fp, "; workspace: %.0f x %.0f mm\n", (double)m->width_mm,
          (double)m->height_mm);
  fprintf(fp, "G21 ; millimeters\n");
  fprintf(fp, "G90 ; absolute positioning\n");
  fprintf(fp, "G94 ; units per minute feed\n");
  fprintf(fp, "G0 Z%.3f ; pen up\n", (double)m->safe_z_mm);
  fprintf(fp, "G0 X0.000 Y0.000 F%.0f ; home\n", (double)m->feed_mm_min);
  lines += 8;

  /* ---- 逐笔画输出 ---- */

  for (s = 0; s < d->nstrokes; s++)
    {
      const struct velaink_stroke *st = &d->strokes[s];
      int i;

      if (st->npts < 2)
        {
          continue;
        }

      for (i = 0; i < st->npts; i++)
        {
          float mx;
          float my;

          velaink_map_point(m, st->pts[i * 2], st->pts[i * 2 + 1], &mx, &my);

          if (!in_bounds(m, mx, my))
            {
              fprintf(fp, "; ERROR point out of bounds (%.2f, %.2f)\n",
                      (double)mx, (double)my);
              lines++;
              return -2;
            }

          if (i == 0)
            {
              /* 快速移动到起笔点上方 -> 落笔 */

              fprintf(fp, "G0 X%.3f Y%.3f\n", (double)mx, (double)my);
              fprintf(fp, "G1 Z%.3f F%.0f ; pen down\n",
                      (double)m->pen_down_mm, (double)m->plunge_mm_min);
              lines += 2;
            }
          else
            {
              fprintf(fp, "G1 X%.3f Y%.3f F%.0f\n", (double)mx, (double)my,
                      (double)m->feed_mm_min);
              lines++;
            }
        }

      /* 抬笔 */

      fprintf(fp, "G1 Z%.3f F%.0f ; pen up\n", (double)m->pen_up_mm,
              (double)m->plunge_mm_min);
      lines++;
    }

  /* ---- 收尾 ---- */

  fprintf(fp, "G0 Z%.3f\n", (double)m->safe_z_mm);
  fprintf(fp, "G0 X0.000 Y0.000 ; return to origin\n");
  fprintf(fp, "M30 ; program end\n");
  lines += 3;

  return lines;
}

int velaink_gcode_to_file(const char *path, const struct velaink_drawing *d,
                          const struct velaink_machine *m)
{
  FILE *fp;
  int   ret;

  fp = fopen(path, "w");
  if (!fp)
    {
      return -1;
    }

  ret = velaink_gcode_emit(fp, d, m);
  fclose(fp);
  return ret;
}

/****************************************************************************
 * apps/packages/demos/contest2026_388_velaink/velaink_main.c
 *
 * 墨灵 VelaInk — openvela 侧笔迹执行器
 *
 * 命令：
 *   velaink demo [step_mm]   生成示例笔迹（一颗心）并输出 G-code
 *   velaink info             打印机器参数
 *   velaink send <gcode> <dev>  把 G-code 文件下发到串口（GRBL 握手）
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include "stroke.h"
#include "gcode.h"

static void usage(void)
{
  printf("Usage:\n");
  printf("  velaink info\n");
  printf("  velaink demo [step_mm]      # default step 0.5mm\n");
  printf("  velaink send <file> <dev>   # e.g. velaink send /tmp/demo.nc "
         "/dev/ttyS1\n");
}

static int cmd_info(void)
{
  struct velaink_machine m;

  velaink_machine_default(&m);
  printf("VelaInk machine profile\n");
  printf("  workspace : %.0f x %.0f mm (margin %.0f)\n", (double)m.width_mm,
         (double)m.height_mm, (double)m.margin_mm);
  printf("  pen       : up %.1f mm / down %.1f mm\n", (double)m.pen_up_mm,
         (double)m.pen_down_mm);
  printf("  feedrate  : draw %.0f / plunge %.0f mm/min\n",
         (double)m.feed_mm_min, (double)m.plunge_mm_min);
  printf("  kinematics: cartesian (CoreXY solved by GRBL board)\n");
  return 0;
}

static int cmd_demo(float step_mm)
{
  struct velaink_drawing  raw;
  struct velaink_drawing  drawn;
  struct velaink_machine  m;
  struct velaink_stroke   smoothed;
  struct velaink_stroke   resampled;
  int                     s;
  int                     ret;
  int                     total_pts = 0;

  velaink_machine_default(&m);

  if (velaink_drawing_init(&raw, 8) < 0)
    {
      printf("velaink: out of memory (raw)\n");
      return -1;
    }

  if (velaink_demo_heart(&raw) < 0)
    {
      printf("velaink: failed to build demo stroke\n");
      velaink_drawing_free(&raw);
      return -1;
    }

  if (velaink_drawing_init(&drawn, 8) < 0)
    {
      printf("velaink: out of memory (drawn)\n");
      velaink_drawing_free(&raw);
      return -1;
    }

  /* 逐笔画：平滑 -> 等距重采样 */

  for (s = 0; s < raw.nstrokes; s++)
    {
      if (raw.strokes[s].npts < 2)
        {
          continue;
        }

      if (velaink_stroke_smooth(&raw.strokes[s], &smoothed, 6) < 0)
        {
          printf("velaink: smooth failed\n");
          break;
        }

      if (velaink_stroke_resample(&smoothed, &resampled, step_mm,
                                  m.width_mm, m.height_mm) < 0)
        {
          printf("velaink: resample failed\n");
          velaink_stroke_free(&smoothed);
          break;
        }

      if (drawn.nstrokes < drawn.cap)
        {
          drawn.strokes[drawn.nstrokes] = resampled;
          drawn.nstrokes++;
          total_pts += resampled.npts;
        }

      velaink_stroke_free(&smoothed);
    }

  printf("; VelaInk demo: %d stroke(s), %d points, step %.2f mm\n",
         drawn.nstrokes, total_pts, (double)step_mm);

  ret = velaink_gcode_emit(stdout, &drawn, &m);
  if (ret < 0)
    {
      printf("velaink: gcode generation failed (%d)\n", ret);
    }
  else
    {
      printf("; generated %d gcode lines\n", ret);

      ret = velaink_gcode_to_file("/tmp/velaink_demo.nc", &drawn, &m);
      if (ret > 0)
        {
          printf("; saved /tmp/velaink_demo.nc\n");
        }
