  return ret < 0 ? -1 : 0;
}

/* GRBL 逐行下发：每行等待 "ok" 应答，保证下位机缓冲区不溢出 */
static int cmd_send(const char *file, const char *dev)
{
  FILE *fp;
  int   fd;
  char  line[160];
  int   sent = 0;

  fp = fopen(file, "r");
  if (!fp)
    {
      printf("velaink: cannot open %s\n", file);
      return -1;
    }

  fd = open(dev, O_RDWR);
  if (fd < 0)
    {
      printf("velaink: cannot open %s\n", dev);
      fclose(fp);
      return -1;
    }

  /* 唤醒 GRBL */
  write(fd, "\r\n\r\n", 4);
  usleep(200000);

  while (fgets(line, sizeof(line), fp))
    {
      size_t len = strlen(line);

      if (len == 0)
        {
          continue;
        }

      if (line[0] == ';')
        {
          continue; /* 跳过注释 */
        }

      write(fd, line, len);

      /* 等待 ok */
      {
        char  buf[64];
        int   got = 0;
        int   tries;

        for (tries = 0; tries < 100 && !got; tries++)
          {
            ssize_t n = read(fd, buf, sizeof(buf) - 1);

            if (n > 0)
              {
                buf[n] = '\0';
                if (strstr(buf, "ok"))
                  {
                    got = 1;
                  }
              }
            else
              {
                usleep(10000);
              }
          }

        if (!got)
          {
            printf("velaink: no ok from GRBL at line %d\n", sent + 1);
            close(fd);
            fclose(fp);
            return -1;
          }
      }

      sent++;
    }

  close(fd);
  fclose(fp);
  printf("velaink: sent %d lines to %s\n", sent, dev);
  return 0;
}

int main(int argc, char *argv[])
{
  if (argc < 2)
    {
      usage();
      return 1;
    }

  if (strcmp(argv[1], "info") == 0)
    {
